"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[91419],{30863:e=>{e.exports=JSON.parse('{"tag":{"label":"Content API","permalink":"/tags/content-api","allTagsPath":"/tags","count":33,"items":[{"id":"cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4","title":"Apollo Server v3 upgraded to Apollo Server v4","description":"The upgrade from Apollo Server v3 to v4 and graphql ^15 to ^16.","permalink":"/cms/migration/v4-to-v5/breaking-changes/upgrade-to-apollov4"},{"id":"cms/api/document-service","title":"Document Service API","description":"The Document Service API is the recommended way to interact with your content from the back-end server or from plugins.","permalink":"/cms/api/document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/use-document-id","title":"documentId should be used instead of id in API calls","description":"Documents should be called by their documentId in Content API calls (REST API & GraphQL).","permalink":"/cms/migration/v4-to-v5/breaking-changes/use-document-id"},{"id":"cms/api/document","title":"Documents","description":"Learn what a Document is in Strapi v5","permalink":"/cms/api/document"},{"id":"cms/api/rest/filters","title":"Filters","description":"Use Strapi\'s REST API to filter the results of your requests.","permalink":"/cms/api/rest/filters"},{"id":"cms/api/graphql","title":"GraphQL API","description":"The GraphQL API allows performing queries and mutations to interact with the content-types through Strapi\'s GraphQL plugin. Results can be filtered, sorted and paginated.","permalink":"/cms/api/graphql"},{"id":"cms/api/rest/guides/populate-creator-fields","title":"How to populate creator fields","description":"Learn how to populate creator fields such as createdBy and updatedBy by creating a custom controller that leverages the populate parameter.","permalink":"/cms/api/rest/guides/populate-creator-fields"},{"id":"cms/api/rest/interactive-query-builder","title":"Interactive Query Builder","description":"Use an interactive tool that leverages the querystring library to build your query URL","permalink":"/cms/api/rest/interactive-query-builder"},{"id":"cms/api/rest/locale","title":"Locale","description":"Browse the REST API reference for the locale parameter to take advantage of the Internationalization feature through REST.","permalink":"/cms/api/rest/locale"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-locale-all","title":"locale=all can not be used to query all locales","description":"In Strapi 5, it\'s no longer possible to get all localized versions with the \'?locale=all\' parameter.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-locale-all"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service","title":"No findPage() in Document Service API","description":"In Strapi 5, the Entity Service API is deprecated, and for the findPage() method you should use the Document Service API\'s findMany() method instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-find-page-in-document-service"},{"id":"cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones","title":"No shared population strategy for components & dynamic zones","description":"In Strapi 5, the shared population strategy is not supported anymore, so components and dynamic zones must be explicitly populated using `on` fragments.","permalink":"/cms/migration/v4-to-v5/breaking-changes/no-shared-population-strategy-components-dynamic-zones"},{"id":"cms/api/rest/parameters","title":"Parameters","description":"Use API parameters to refine your Strapi REST API queries.","permalink":"/cms/api/rest/parameters"},{"id":"cms/api/rest/populate-select","title":"Populate and Select","description":"Use Strapi\'s REST API to populate or select certain fields.","permalink":"/cms/api/rest/populate-select"},{"id":"cms/migration/v4-to-v5/breaking-changes/publication-state-removed","title":"publicationState is removed and replaced by status","description":"In Strapi 5, \'publicationState\' can no longer be used in Content API calls. The new status parameter can be used and accepts 2 different values, draft and published.","permalink":"/cms/migration/v4-to-v5/breaking-changes/publication-state-removed"},{"id":"cms/api/rest/relations","title":"Relations","description":"Use the REST API to manage the order of relations","permalink":"/cms/api/rest/relations"},{"id":"cms/migration/v4-to-v5/breaking-changes/attributes-and-content-types-names-reserved","title":"Reserved attributes and content-types names","description":"In Strapi 5, some attributes and content types names are reserved, and all fields or content types using the reserved names should be renamed before migrating to prevent data loss.","permalink":"/cms/migration/v4-to-v5/breaking-changes/attributes-and-content-types-names-reserved"},{"id":"cms/api/rest/guides/intro","title":"REST API Guides","description":"Deep dive into some specific REST API topics using guides that extensively explain some use cases or give step-by-step instructions.","permalink":"/cms/api/rest/guides/intro"},{"id":"cms/api/rest","title":"REST API reference","description":"Interact with your Content-Types using the REST API endpoints Strapi generates for you.","permalink":"/cms/api/rest"},{"id":"cms/api/rest/sort-pagination","title":"Sort and Pagination","description":"Use Strapi\'s REST API to sort or paginate your data.","permalink":"/cms/api/rest/sort-pagination"},{"id":"cms/migration/v4-to-v5/breaking-changes/sort-by-id","title":"Sorting by id is no longer possible to sort by chronological order","description":"In Strapi 5, sorting by id is no longer possible to sort by chronological order, and you should use createdAt instead.","permalink":"/cms/migration/v4-to-v5/breaking-changes/sort-by-id"},{"id":"cms/api/rest/status","title":"Status","description":"Use Strapi\'s REST API to work with draft or published versions of your documents.","permalink":"/cms/api/rest/status"},{"id":"cms/migration/v4-to-v5/breaking-changes/new-response-format","title":"Strapi 5 has a new, flattened response format for API calls","description":"In Strapi 5, the response format has been simplified and flattened, and attributes of requested content are no longer wrapped in an attributes object.","permalink":"/cms/migration/v4-to-v5/breaking-changes/new-response-format"},{"id":"cms/api/client","title":"Strapi Client","description":"The Strapi Client library simplifies interactions with your Strapi back end, providing a way to fetch, create, update, and delete content.","permalink":"/cms/api/client"},{"id":"cms/migration/v4-to-v5/breaking-changes/graphql-api-updated","title":"The GraphQL API has been updated","description":"In Strapi 5, the GraphQL API has been updated. It handles the new, flattened response format, and can also now accept Relay-style queries.","permalink":"/cms/migration/v4-to-v5/breaking-changes/graphql-api-updated"},{"id":"cms/api/rest/guides/understanding-populate","title":"Understanding populate","description":"Learn what populating means and how you can use the populate parameter in your REST API queries to add additional fields to your responses.","permalink":"/cms/api/rest/guides/understanding-populate"},{"id":"cms/api/rest/upload","title":"Upload files","description":"Learn how to use the /api/upload endpoints to upload files to Strapi with the REST API.","permalink":"/cms/api/rest/upload"},{"id":"cms/api/document-service/status","title":"Using Draft & Publish with the Document Service API","description":"Use Strapi\'s Document Service API to return either the draft or the published version of a document","permalink":"/cms/api/document-service/status"},{"id":"cms/api/document-service/fields","title":"Using fields with the Document Service API","description":"Use Strapi\'s Document Service API to select the fields to return with your queries.","permalink":"/cms/api/document-service/fields"},{"id":"cms/api/document-service/filters","title":"Using filters with the Document Service API","description":"This document provides information about the filters available in the Document Service API.","permalink":"/cms/api/document-service/filters"},{"id":"cms/api/document-service/populate","title":"Using Populate with the Document Service API","description":"Use Strapi\'s Document Service API to populate or select some fields.","permalink":"/cms/api/document-service/populate"},{"id":"cms/api/document-service/sort-pagination","title":"Using Sort & Pagination with the Document Service API","description":"Use Strapi\'s Document Service API to sort and paginate query results","permalink":"/cms/api/document-service/sort-pagination"},{"id":"cms/api/document-service/locale","title":"Using the locale parameter with the Document Service API","description":"Use Strapi\'s Document Service API to work with locale versions with your queries.","permalink":"/cms/api/document-service/locale"}],"unlisted":false}}')}}]);